// Ported from the Node app's Sequelize model JobApplicant (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class JobApplicantConfiguration : IEntityTypeConfiguration<JobApplicant>
{
    public void Configure(EntityTypeBuilder<JobApplicant> builder)
    {
        builder.ToTable("job_applicants", t =>
        {
            t.HasCheckConstraint("CK_job_applicants_status", "[status] IN (N'applied', N'shortlisted', N'interviewed', N'offered', N'hired', N'rejected')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.OpeningId).HasColumnName("opening_id");
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(160)").HasMaxLength(160).IsRequired();
        builder.Property(e => e.Email).HasColumnName("email").HasColumnType("nvarchar(150)").HasMaxLength(150);
        builder.Property(e => e.Phone).HasColumnName("phone").HasColumnType("nvarchar(20)").HasMaxLength(20);
        builder.Property(e => e.Qualification).HasColumnName("qualification").HasColumnType("nvarchar(160)").HasMaxLength(160);
        builder.Property(e => e.Notes).HasColumnName("notes").HasColumnType("nvarchar(500)").HasMaxLength(500);
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'applied'");
        builder.Property(e => e.StaffId).HasColumnName("staff_id");
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("datetime2");
        builder.HasOne(e => e.JobOpening).WithMany(p => p.JobApplicants).HasForeignKey(e => e.OpeningId).OnDelete(DeleteBehavior.NoAction);
    }
}
